    // ══════════════════════════════════════════════════════════════════════

    case 'daftra_save_cookie': {
        // جلسة دفترة مفتاح لكل مستنداتنا — لا تُكتب إلا بصلاحية مالية مؤكدة
        if (!$_jwt_claims || empty($_jwt_claims['sub'])) {
            echo json_encode(['success'=>false,'message'=>'يتطلب تسجيل الدخول'], JSON_UNESCAPED_UNICODE); break; }
        $cu = null;
        if ($r = $conn->query("SELECT name, role, permissions FROM users WHERE id=" . (int)$_jwt_claims['sub'] . " LIMIT 1"))
            $cu = $r->fetch_assoc();
        $cp = json_decode((string)($cu['permissions'] ?? '[]'), true); if (!is_array($cp)) $cp = [];
        if (!$cu || (($cu['role'] ?? '') !== 'admin' && !in_array('finance', $cp, true))) {
            echo json_encode(['success'=>false,'message'=>'لا تملك صلاحية تعديل الربط'], JSON_UNESCAPED_UNICODE); break; }
        $body   = json_decode(file_get_contents('php://input'), true) ?? [];
        $cookie = trim($body['cookie'] ?? '');
        if ($cookie === '') { echo json_encode(['success'=>false,'message'=>'الكوكي فارغ'], JSON_UNESCAPED_UNICODE); break; }
        [$fresh, $names] = daftra_normalize_cookie($cookie);
        if ($fresh === '') {
            echo json_encode(['success'=>false,
                'message'=>'ما وجدت أي كوكي في النص — انسخ سطر Cookie أو كتلة set-cookie كاملة'],
                JSON_UNESCAPED_UNICODE); break;
        }
        // دفترة تطبيقان: /owner يعمل بـ CAKEPHP و/v2 بـ laravel_session.
        // لصقة من أحدهما لا يجوز أن تمحو كوكيز الآخر، فندمج والأحدث يغلب.
        if (empty($body['replace'])) {
            [$old] = daftra_normalize_cookie(daftra_session_cookie($conn));
            if ($old !== '') {
                [$cookie, $names] = daftra_normalize_cookie($old . '; ' . $fresh);
            } else { $cookie = $fresh; }
        } else { $cookie = $fresh; }
        $esc = $conn->real_escape_string($cookie);
        $conn->query("INSERT INTO daftra_config (k,v) VALUES ('session_cookie','$esc')
                      ON DUPLICATE KEY UPDATE v='$esc'");
        // اختبار على مرفق حقيقي من مرفقاتنا — هو الغرض من الجلسة أصلاً
        $ok = false; $why = ''; $tfid = 0;
        if ($r = $conn->query("SELECT file_id FROM dmirror_attachments
                WHERE entity_key IN ('purchase_order','purchase_invoice') ORDER BY file_id DESC LIMIT 1"))
            if ($x = $r->fetch_assoc()) $tfid = (int)$x['file_id'];
        if ($tfid > 0) {
            [$tb, $tc, $tr] = daftra_file_bytes($conn, $tfid);
            $ok  = ($tb !== null);
            $why = $ok ? (string)$tr : mb_substr((string)$tr, 0, 300);
        } else {
            // لا مرفقات في المرآة بعد — نكتفي بفحص صفحة تتطلب دخولاً
            $ch = curl_init("https://semak.daftra.com/owner/invoices/index");
            curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_FOLLOWLOCATION=>false, CURLOPT_TIMEOUT=>20,
                CURLOPT_HTTPHEADER=>["Cookie: $cookie"], CURLOPT_USERAGENT=>'Mozilla/5.0 SemakProxy']);
            $tb2 = curl_exec($ch); $c2 = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
            $ok  = ($c2 === 200 && $tb2 && stripos((string)$tb2, 'login') === false);
            $why = 'index:' . $c2;
        }
        acc_audit($conn, 1, 'settings', 0, 'daftra_cookie',
            'تحديث جلسة دفترة — ' . ($ok ? 'صالحة' : 'غير مؤكدة') . ' — ' . implode(', ', $names),
            (string)($cu['name'] ?? ''));
        $hasCake = false; $hasLar = false;
        foreach ($names as $n) {
            if (strcasecmp($n, 'CAKEPHP') === 0) $hasCake = true;
            if (strcasecmp($n, 'laravel_session') === 0) $hasLar = true;
        }
        $missing = [];
        if (!$hasCake) $missing[] = 'CAKEPHP (تطبيق /owner)';
        if (!$hasLar)  $missing[] = 'laravel_session (تطبيق /v2 — مصدر المرفقات)';
        echo json_encode(['success'=>true, 'valid'=>$ok, 'cookies'=>$names, 'tested_file'=>$tfid,
            'detail'=>$why, 'has_cakephp'=>$hasCake, 'has_laravel'=>$hasLar,
            'missing'=>$missing,
            'message'=>($ok ? 'تم الحفظ والكوكي صالح ✓ — جلبت مرفقاً تجريبياً بنجاح'
                            : ('تم الحفظ لكن تعذر جلب مرفق تجريبي'
                               . ($missing ? ' — ناقص: ' . implode('، ', $missing) : ' — ' . $why))),
            'read'=>count($names)], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        break;
    }

    case 'daftra_cookie_status':
        if (!$_jwt_claims || empty($_jwt_claims['sub'])) {
            echo json_encode(['success'=>false,'message'=>'يتطلب تسجيل الدخول'], JSON_UNESCAPED_UNICODE); break; }
        $r = $conn->query("SELECT v, updated_at FROM daftra_config WHERE k='session_cookie' LIMIT 1");
        $row = $r ? $r->fetch_assoc() : null;
        $set = $row && !empty(trim($row['v']));
        echo json_encode([
            'success'    => true,
            'set'        => $set,
            'updated_at' => $row['updated_at'] ?? null,
            'preview'    => $set ? substr($row['v'],0,14).'…' : '',
        ], JSON_UNESCAPED_UNICODE);
        break;

    // ══════════════════════════════════════════════════════════════════════
    // PDF الرسمي من دفترة (عربي صحيح + ZATCA QR) — proxy بالجلسة المخزّنة
    // ══════════════════════════════════════════════════════════════════════

    case 'daftra_doc_pdf':
        // type: invoice | estimate | purchase   id: رقم المستند
        $type    = $_GET['type'] ?? 'invoice';
        $doc_id  = (int)($_GET['id'] ?? 0);
        $session = daftra_session_cookie($conn);
        if (!$doc_id) { echo json_encode(['success'=>false,'message'=>'id مطلوب']); break; }

        // مسارات الطباعة المرشّحة حسب نوع المستند (دفترة تولّد PDF عربي + QR)
        // الأنماط الصحيحة المؤكّدة من نظام دفترة الحيّ:
        //   فاتورة:  /owner/invoices/view/{id}.pdf   (وطباعة: /owner/invoices/view/{id}/print:1)
        $paths = [
            'invoice'  => ["/owner/invoices/view/$doc_id.pdf", "/owner/invoices/view/$doc_id/print:1"],
            'estimate' => ["/owner/invoices/view_estimate/$doc_id.pdf", "/owner/estimates/view/$doc_id.pdf", "/owner/invoices/view/$doc_id.pdf"],
            'purchase' => ["/owner/purchase_invoices/view/$doc_id.pdf", "/owner/purchase_invoices/view/$doc_id/print:1"],
        ];
        $candidates = $paths[$type] ?? $paths['invoice'];

        $pdf_body = null; $pdf_ctype = null; $tried = [];
        foreach ($candidates as $path) {
            $url = "https://semak.daftra.com$path";
            $ch  = curl_init($url);
            curl_setopt_array($ch, [
                CURLOPT_RETURNTRANSFER => true,
                CURLOPT_FOLLOWLOCATION => true,
                CURLOPT_TIMEOUT        => 25,
                CURLOPT_HTTPHEADER     => ["Cookie: $session", "Accept: application/pdf,text/html"],
                CURLOPT_USERAGENT      => 'Mozilla/5.0 SemakProxy',
            ]);
            $body  = curl_exec($ch);
            $code  = curl_getinfo($ch, CURLINFO_HTTP_CODE);
            $ctype = curl_getinfo($ch, CURLINFO_CONTENT_TYPE);
            curl_close($ch);
            $tried[] = ['path'=>$path, 'code'=>$code, 'ctype'=>$ctype, 'len'=>strlen($body ?? '')];
            // PDF حقيقي يبدأ بـ %PDF
            if ($body && (stripos($ctype, 'pdf') !== false || substr($body, 0, 4) === '%PDF')) {
                $pdf_body  = $body; $pdf_ctype = 'application/pdf'; break;
            }
        }

        if ($pdf_body !== null) {
            ob_end_clean();
            header_remove('Content-Type');
            header('Content-Type: application/pdf');
            header('Content-Disposition: inline; filename="'.$type.'_'.$doc_id.'.pdf"');
            header('Cache-Control: private, max-age=0, must-revalidate');
            echo $pdf_body;
            exit(0);
        }

        // فشل جلب PDF عبر جلسة الخادم (كوكي منتهي) — تدرّج سلس:
        // إن طُلب JSON صراحةً نُرجع تفاصيل التشخيص، وإلا نحوّل المتصفّح مباشرة
        // لرابط دفترة (يفتح بجلسة متصفّح المستخدم إن كان مسجّلاً في دفترة).
        $debug = isset($_GET['debug']);
        if ($debug) {
            echo json_encode([
                'success'   => false,
                'message'   => 'تعذّر جلب PDF عبر جلسة الخادم — الكوكي منتهي',
                'print_url' => "https://semak.daftra.com".$candidates[0],
                'tried'     => $tried,
            ], JSON_UNESCAPED_UNICODE);
        } else {
            ob_end_clean();
            header_remove('Content-Type');
            header('Location: https://semak.daftra.com'.$candidates[0], true, 302);
        }
        exit(0);

