            $conn->query("INSERT IGNORE INTO purchase_documents
                (purchase_id, invoice_no, doc_type, file_name, drive_folder, daftra_file_id, source, confidence, note)
                VALUES ($pid, '" . $E($no) . "', '" . $E($type) . "', '" . $E($name) . "', '$folder', "
                . (int)($row['daftra_file_id'] ?? 0) . ", 'recovered', '" . $E($row['confidence'] ?? '') . "', '"
                . $E($row['note'] ?? '') . "')");
            if ($conn->affected_rows > 0) $added++; else $skipped++;
        }
        echo json_encode(['success'=>true, 'added'=>$added, 'skipped'=>$skipped], JSON_UNESCAPED_UNICODE);
        break;
    }

    case 'dmirror_sync_lite': {
        // مزامنة خفيفة: أحدث صفحة من دفترة فقط — تُستدعى مع كل فتح للتطبيق
        // المزامنة الكاملة تبقى في dmirror_sync للمراجعات الدورية.
        set_time_limit(60);
        $dk    = "__DAFTRA_KEY__";
        $take  = min(100, max(10, (int)($_GET['limit'] ?? 40)));
        $force = !empty($_GET['force']);

        // خانق: لا نطرق دفترة أكثر من مرة كل دقيقتين إلا بطلب صريح
        $last = null;
        if ($r = $conn->query("SELECT synced_at FROM daftra_sync_log WHERE entity='purchases_lite' LIMIT 1"))
            if ($x = $r->fetch_assoc()) $last = $x['synced_at'];
        if (!$force && $last && (time() - strtotime($last)) < 120) {
            echo json_encode(['success'=>true, 'skipped'=>true, 'last'=>$last,
                'message'=>'آخر مزامنة قبل قليل'], JSON_UNESCAPED_UNICODE); break;
        }

        $ch = curl_init("https://semak.daftra.com/api2/purchase_invoices.json?page=1&limit=$take");
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_FOLLOWLOCATION=>true, CURLOPT_TIMEOUT=>25,
            CURLOPT_HTTPHEADER=>["APIKEY: $dk", "Accept: application/json"]]);
        $res  = curl_exec($ch);
        $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);
        if ($code !== 200 || !$res) {
            echo json_encode(['success'=>false, 'message'=>'تعذر الاتصال بدفترة', 'http'=>$code], JSON_UNESCAPED_UNICODE); break;
        }
        $d = json_decode($res, true) ?: [];
        $added = 0; $updated = 0; $seen = 0; $need = [];

        foreach (($d['data'] ?? []) as $it) {
            $p = $it['PurchaseOrder'] ?? $it['PurchaseInvoice'] ?? $it;
            if (empty($p['id'])) continue;
            $id = (int)$p['id']; $seen++;
            $no   = $conn->real_escape_string((string)($p['no'] ?? ''));
            $date = preg_match('/^\d{4}-\d{2}-\d{2}/', (string)($p['date'] ?? '')) ? substr($p['date'], 0, 10)
                  : (preg_match('#^(\d{2})/(\d{2})/(\d{4})#', (string)($p['date'] ?? ''), $m) ? "$m[3]-$m[2]-$m[1]" : null);
            $sid  = (int)($p['supplier_id'] ?? 0);
            $sup  = $conn->real_escape_string((string)($p['supplier_business_name'] ?? $p['supplier'] ?? ''));
            $tot  = (float)($p['summary_total'] ?? 0);
            $sub  = (float)($p['summary_subtotal'] ?? 0);
            $paid = (float)($p['summary_paid'] ?? 0);
            $wo   = isset($p['work_order_id']) && $p['work_order_id'] !== null ? (int)$p['work_order_id'] : 'NULL';
            $cr   = !empty($p['created'])  ? "'" . $conn->real_escape_string($p['created'])  . "'" : 'NULL';
            $mo   = !empty($p['modified']) ? "'" . $conn->real_escape_string($p['modified']) . "'" : 'NULL';
            $raw  = $conn->real_escape_string(json_encode($p, JSON_UNESCAPED_UNICODE));
            $dsql = $date ? "'$date'" : 'NULL';

            $old = null;
            if ($r = $conn->query("SELECT total, paid FROM dmirror_purchases WHERE id=$id LIMIT 1")) $old = $r->fetch_assoc();
            $conn->query("INSERT INTO dmirror_purchases
                    (id,no,date,supplier_id,supplier,total,subtotal,paid,work_order_id,created,modified,raw,origin)
                VALUES ($id,'$no',$dsql,$sid,'$sup',$tot,$sub,$paid,$wo,$cr,$mo,'$raw','daftra')
                ON DUPLICATE KEY UPDATE no=VALUES(no), date=VALUES(date), supplier_id=VALUES(supplier_id),
                    supplier=VALUES(supplier), total=VALUES(total), subtotal=VALUES(subtotal), paid=VALUES(paid),
                    work_order_id=VALUES(work_order_id), modified=VALUES(modified), raw=VALUES(raw)");
            if (!$old) { $added++; $need[] = $id; }
            elseif (abs((float)$old['total'] - $tot) > 0.009 || abs((float)$old['paid'] - $paid) > 0.009) { $updated++; $need[] = $id; }
            // فاتورة جديدة ترث تسكين دفترة إن وُجد
            if ($wo !== 'NULL')
                $conn->query("INSERT IGNORE INTO purchase_project (purchase_id, project_id, note, set_by)
                              VALUES ($id, $wo, 'موروث من دفترة عند المزامنة', 'system')");
        }
        // إعادة تفصيل صريحة لأحدث الفواتير — لالتقاط ما استُجدّ عليها
        $redetail = min(20, max(0, (int)($_GET['redetail'] ?? 0)));
        if ($redetail > 0 && ($q = $conn->query("SELECT id FROM dmirror_purchases
                WHERE COALESCE(origin,'daftra')='daftra' ORDER BY id DESC LIMIT $redetail")))
            while ($r = $q->fetch_assoc()) $need[] = (int)$r['id'];

        // فواتير مرآتنا بلا بنود (تشمل ما وصل سابقاً من المزامنة الخفيفة)
        if (count($need) < 12) {
            if ($q = $conn->query("SELECT p.id FROM dmirror_purchases p
                    LEFT JOIN dmirror_purchase_items i ON i.purchase_id = p.id
                    WHERE i.id IS NULL AND (p.origin IS NULL OR p.origin='daftra')
                    GROUP BY p.id ORDER BY p.id DESC LIMIT 12")) {
                while ($r = $q->fetch_assoc()) $need[] = (int)$r['id'];
            }
        }
        $need = array_slice(array_values(array_unique($need)), 0, max(12, $redetail));

        // جلب تفاصيل كل فاتورة محتاجة: البنود والدفعات والمرفقات + تغذية متابعة الأسعار
        $items_done = 0; $payKeys = []; $payAtt = [];
        foreach ($need as $pid) {
            $ch = curl_init("https://semak.daftra.com/api2/purchase_invoices/$pid.json");
            curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_FOLLOWLOCATION=>true, CURLOPT_TIMEOUT=>20,
                CURLOPT_HTTPHEADER=>["APIKEY: $dk", "Accept: application/json"]]);
            $rr = curl_exec($ch); $cc = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
            if ($cc !== 200 || !$rr) continue;
            $dd = json_decode($rr, true) ?: [];
            $o  = $dd['data']['PurchaseOrder'] ?? $dd['data']['PurchaseInvoice'] ?? null;
            if (!$o) continue;

            $idate = null; $isup = '';
            if ($r2 = $conn->query("SELECT date, supplier FROM dmirror_purchases WHERE id=$pid LIMIT 1"))
                if ($x2 = $r2->fetch_assoc()) { $idate = $x2['date']; $isup = (string)$x2['supplier']; }
            $dsql2 = $idate ? "'" . $conn->real_escape_string($idate) . "'" : 'NULL';

            $items = (array)($o['PurchaseOrderItem'] ?? $o['PurchaseInvoiceItem'] ?? []);
            if ($items) $conn->query("DELETE FROM purchase_product_items WHERE ref_id=$pid");
            foreach ($items as $it) {
                $it = $it['PurchaseOrderItem'] ?? $it['PurchaseInvoiceItem'] ?? $it;
                if (!isset($it['id'])) continue;
                $qty  = (float)($it['quantity'] ?? 0);
                $up   = (float)($it['unit_price'] ?? 0);
                $line = (float)($it['subtotal'] ?? 0);
                if ($line <= 0) $line = $up * ($qty ?: 1);
                $conn->query("REPLACE INTO dmirror_purchase_items
                    (id,purchase_id,item,description,quantity,unit_price,discount,tax1,subtotal,product_id) VALUES ("
                    . (int)$it['id'] . ", $pid, '" . $conn->real_escape_string((string)($it['item'] ?? $it['name'] ?? '')) . "', '"
                    . $conn->real_escape_string((string)($it['description'] ?? '')) . "', $qty, $up, "
                    . (float)($it['discount'] ?? 0) . ", '" . $conn->real_escape_string((string)($it['tax1'] ?? '')) . "', "
                    . $line . ", " . (int)($it['product_id'] ?? 0) . ")");
                $prid = (int)($it['product_id'] ?? 0);
                if ($prid > 0 && $qty > 0)
                    $conn->query("INSERT INTO purchase_product_items (ref_id, product_id, amount, qty, inv_date, supplier)
                        VALUES ($pid, $prid, $line, $qty, $dsql2, '" . $conn->real_escape_string($isup) . "')
                        ON DUPLICATE KEY UPDATE amount=VALUES(amount), qty=VALUES(qty),
                            inv_date=VALUES(inv_date), supplier=VALUES(supplier)");
            }
            foreach ((array)($o['PurchaseOrderPayment'] ?? []) as $pay) {
                $pay = $pay['PurchaseOrderPayment'] ?? $pay;
                if (!isset($pay['id'])) continue;
                // إيصال السداد قد يكون مرفقاً على الدفعة نفسها
                foreach ((array)($pay['Attachments'] ?? $pay['attachments'] ?? []) as $pa) {
                    if (!isset($pa['id'])) continue;
                    $conn->query("REPLACE INTO dmirror_attachments
                        (file_id,name,path,entity_key,entity_id,file_size,mime_type,created_at) VALUES ("
                        . (int)$pa['id'] . ", '" . $conn->real_escape_string((string)($pa['name'] ?? '')) . "', '"
                        . $conn->real_escape_string((string)($pa['path'] ?? '')) . "', 'purchase_order_payment', "
                        . (int)$pay['id'] . ", " . (int)($pa['file_size'] ?? 0) . ", '"
                        . $conn->real_escape_string((string)($pa['mime_type'] ?? '')) . "', "
                        . (!empty($pa['created_at']) ? "'" . $conn->real_escape_string($pa['created_at']) . "'" : 'NULL') . ")");
                }
                foreach (array_keys($pay) as $pk) $payKeys[] = $pk;
                $pd = preg_match('/^\d{4}-\d{2}-\d{2}/', (string)($pay['date'] ?? '')) ? "'" . substr($pay['date'],0,10) . "'" : 'NULL';
                $att = trim((string)($pay['attachment'] ?? ''));
                if ($att !== '') $payAtt[] = $att;
                $conn->query("REPLACE INTO dmirror_payments
                        (id,purchase_id,amount,date,treasury_id,created,
                         attachment,payment_method,transaction_id,receipt_notes,notes) VALUES ("
                    . (int)$pay['id'] . ", $pid, " . (float)($pay['amount'] ?? 0) . ", $pd, "
                    . (int)($pay['treasury_id'] ?? 0) . ", "
                    . (!empty($pay['created']) ? "'" . $conn->real_escape_string($pay['created']) . "'" : 'NULL') . ", '"
                    . $conn->real_escape_string(mb_substr($att, 0, 390)) . "', '"
                    . $conn->real_escape_string(mb_substr((string)($pay['payment_method'] ?? ''), 0, 70)) . "', '"
                    . $conn->real_escape_string(mb_substr((string)($pay['transaction_id'] ?? ''), 0, 110)) . "', '"
                    . $conn->real_escape_string(mb_substr((string)($pay['receipt_notes'] ?? ''), 0, 490)) . "', '"
                    . $conn->real_escape_string(mb_substr((string)($pay['notes'] ?? ''), 0, 490)) . "')");
            }
            $att = (array)($o['Attachments'] ?? []);
            foreach ($att as $a) {
                if (!isset($a['id'])) continue;
                $conn->query("REPLACE INTO dmirror_attachments
                    (file_id,name,path,entity_key,entity_id,file_size,mime_type,created_at) VALUES ("
                    . (int)$a['id'] . ", '" . $conn->real_escape_string((string)($a['name'] ?? '')) . "', '"
                    . $conn->real_escape_string((string)($a['path'] ?? '')) . "', '"
                    . $conn->real_escape_string((string)($a['entity_key'] ?? 'purchase_order')) . "', $pid, "
                    . (int)($a['file_size'] ?? 0) . ", '" . $conn->real_escape_string((string)($a['mime_type'] ?? '')) . "', "
                    . (!empty($a['created_at']) ? "'" . $conn->real_escape_string($a['created_at']) . "'" : 'NULL') . ")");
            }
            $conn->query("UPDATE dmirror_purchases SET items_count=" . count($items) . ", attachments=" . count($att) . " WHERE id=$pid");
            if ($items) $items_done++;
        }

        $conn->query("INSERT INTO daftra_sync_log (entity, count, synced_at, synced_by)
                      VALUES ('purchases_lite', $seen, NOW(), 'app')
                      ON DUPLICATE KEY UPDATE count=VALUES(count), synced_at=NOW(), synced_by=VALUES(synced_by)");
        $out = ['success'=>true, 'checked'=>$seen, 'added'=>$added, 'updated'=>$updated,
                'items_synced'=>$items_done];
        if ($redetail > 0) {
            $out['payment_keys'] = array_values(array_unique($payKeys));
            $out['payment_attachments'] = array_slice(array_values(array_unique($payAtt)), 0, 8);
        }
        if ($r2 = $conn->query("SELECT COUNT(*) n FROM dmirror_payments WHERE COALESCE(attachment,'') <> ''"))
            if ($x2 = $r2->fetch_assoc()) $out['payments_with_attachment'] = (int)$x2['n'];
        echo json_encode($out, JSON_UNESCAPED_UNICODE);
        break;
    }

    case 'dmirror_sync': {
        set_time_limit(300);
        $dk   = "__DAFTRA_KEY__";
        $base = "https://semak.daftra.com/api2";
        $hdrs = ["APIKEY: $dk", "Accept: application/json"];
        $deep = !empty($_GET['deep']);          // deep=1 يجلب بنود كل فاتورة (أبطأ)
        $limit_deep = (int)($_GET['deep_limit'] ?? 60);

        $get = function($url) use ($hdrs) {
            $ch = curl_init($url);
            curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_HTTPHEADER=>$hdrs,
                CURLOPT_TIMEOUT=>25, CURLOPT_FOLLOWLOCATION=>true]);
            $r = curl_exec($ch); $c = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
            return $c === 200 ? (json_decode($r, true) ?: null) : null;
        };

        $conn->query("INSERT INTO dmirror_runs (scope) VALUES ('" . ($deep ? 'deep' : 'list') . "')");
        $run_id = (int)$conn->insert_id;
        $fetched = 0; $changed = 0; $errors = [];

        // 1) قائمة فواتير الشراء (كل الصفحات)
        $rows = [];
        for ($page = 1; $page <= 40; $page++) {
            $d = $get("$base/purchase_invoices.json?page=$page&limit=100");
            if (!$d || empty($d['data'])) break;
            foreach ($d['data'] as $it) {
                $p = $it['PurchaseOrder'] ?? $it['PurchaseInvoice'] ?? $it;
                if (!isset($p['id'])) continue;
                $rows[(int)$p['id']] = $p;
            }
            if (count($d['data']) < 100) break;
        }
        $fetched = count($rows);

        // 2) الحفظ مع رصد التغييرات مقابل النسخة السابقة
        $prev = [];
        if ($pr = $conn->query("SELECT id, no, total, paid, work_order_id FROM dmirror_purchases")) {
            while ($r = $pr->fetch_assoc()) $prev[(int)$r['id']] = $r;
        }
        foreach ($rows as $id => $p) {
            $no    = $conn->real_escape_string((string)($p['no'] ?? ''));
            $date  = preg_match('/^\d{4}-\d{2}-\d{2}/', (string)($p['date'] ?? '')) ? substr($p['date'],0,10)
                   : (preg_match('#^(\d{2})/(\d{2})/(\d{4})#', (string)($p['date'] ?? ''), $m) ? "$m[3]-$m[2]-$m[1]" : null);
            $sid   = (int)($p['supplier_id'] ?? 0);
            $sup   = $conn->real_escape_string((string)($p['supplier_business_name'] ?? $p['supplier'] ?? ''));
            $tot   = (float)($p['summary_total'] ?? 0);
            $sub   = (float)($p['summary_subtotal'] ?? 0);
            $paid  = (float)($p['summary_paid'] ?? 0);
            $adj   = (float)($p['adjustment_value'] ?? 0);
            $wo    = isset($p['work_order_id']) && $p['work_order_id'] !== null ? (int)$p['work_order_id'] : 'NULL';
            $cr    = !empty($p['created'])  ? "'" . $conn->real_escape_string($p['created'])  . "'" : 'NULL';
            $mo    = !empty($p['modified']) ? "'" . $conn->real_escape_string($p['modified']) . "'" : 'NULL';
            $raw   = $conn->real_escape_string(json_encode($p, JSON_UNESCAPED_UNICODE));
            $dsql  = $date ? "'$date'" : 'NULL';

            if (isset($prev[$id])) {
                $o = $prev[$id];
                foreach ([['no',(string)$o['no'],$no], ['total',(float)$o['total'],$tot],
                          ['paid',(float)$o['paid'],$paid],
                          ['work_order_id',(string)$o['work_order_id'],(string)($wo==='NULL'?'':$wo)]] as $chk) {
                    [$f, $ov, $nv] = $chk;
                    $diff = is_float($ov) ? (abs($ov - (float)$nv) > 0.009) : ((string)$ov !== (string)$nv);
                    if ($diff) {
                        $changed++;
                        $conn->query("INSERT INTO dmirror_changes (run_id, entity, entity_id, field, old_value, new_value)
                            VALUES ($run_id, 'purchase', $id, '" . $conn->real_escape_string($f) . "',
                            '" . $conn->real_escape_string((string)$ov) . "', '" . $conn->real_escape_string((string)$nv) . "')");
                    }
                }
            }
            $conn->query("REPLACE INTO dmirror_purchases
                (id,no,date,supplier_id,supplier,total,subtotal,paid,adjustment,work_order_id,created,modified,raw)
                VALUES ($id,'$no',$dsql,$sid,'$sup',$tot,$sub,$paid,$adj,$wo,$cr,$mo,'$raw')");
        }

        // 3) البنود والدفعات (اختياري — للفواتير الأحدث أو غير المجلوبة بعد)
        $deep_done = 0;
        if ($deep) {
            $need = [];
            if ($q = $conn->query("SELECT p.id FROM dmirror_purchases p
                    LEFT JOIN dmirror_purchase_items i ON i.purchase_id = p.id
                    WHERE i.id IS NULL GROUP BY p.id ORDER BY p.id DESC LIMIT $limit_deep")) {
                while ($r = $q->fetch_assoc()) $need[] = (int)$r['id'];
            }
            foreach ($need as $pid) {
                $d = $get("$base/purchase_invoices/$pid.json");
                $o = $d['data']['PurchaseOrder'] ?? $d['data']['PurchaseInvoice'] ?? null;
                if (!$o) { $errors[] = $pid; continue; }
                $items = (array)($o['PurchaseOrderItem'] ?? $o['PurchaseInvoiceItem'] ?? []);
                foreach ($items as $it) {
                    if (!isset($it['id'])) continue;
                    $conn->query("REPLACE INTO dmirror_purchase_items
                        (id,purchase_id,item,description,quantity,unit_price,discount,tax1,subtotal,product_id) VALUES ("
                        . (int)$it['id'] . ", $pid, '" . $conn->real_escape_string((string)($it['item'] ?? $it['name'] ?? '')) . "', '"
                        . $conn->real_escape_string((string)($it['description'] ?? '')) . "', "
                        . (float)($it['quantity'] ?? 0) . ", " . (float)($it['unit_price'] ?? 0) . ", "
                        . (float)($it['discount'] ?? 0) . ", '" . $conn->real_escape_string((string)($it['tax1'] ?? '')) . "', "
                        . (float)($it['subtotal'] ?? 0) . ", " . (int)($it['product_id'] ?? 0) . ")");
                }
                foreach ((array)($o['PurchaseOrderPayment'] ?? []) as $pay) {
                    if (!isset($pay['id'])) continue;
                    $pd = preg_match('/^\d{4}-\d{2}-\d{2}/', (string)($pay['date'] ?? '')) ? "'" . substr($pay['date'],0,10) . "'" : 'NULL';
                    $conn->query("REPLACE INTO dmirror_payments (id,purchase_id,amount,date,treasury_id,created) VALUES ("
                        . (int)$pay['id'] . ", $pid, " . (float)($pay['amount'] ?? 0) . ", $pd, "
                        . (int)($pay['treasury_id'] ?? 0) . ", " . (!empty($pay['created']) ? "'" . $conn->real_escape_string($pay['created']) . "'" : 'NULL') . ")");
                }
                $att = (array)($o['Attachments'] ?? []);
                foreach ($att as $a) {
                    if (!isset($a['id'
])) continue;
                    $conn->query("REPLACE INTO dmirror_attachments (file_id,name,path,entity_key,entity_id,file_size,mime_type,created_at) VALUES ("
                        . (int)$a['id'] . ", '" . $conn->real_escape_string((string)($a['name'] ?? '')) . "', '"
                        . $conn->real_escape_string((string)($a['path'] ?? '')) . "', '"
                        . $conn->real_escape_string((string)($a['entity_key'] ?? 'purchase_order')) . "', $pid, "
                        . (int)($a['file_size'] ?? 0) . ", '" . $conn->real_escape_string((string)($a['mime_type'] ?? '')) . "', "
                        . (!empty($a['created_at']) ? "'" . $conn->real_escape_string($a['created_at']) . "'" : 'NULL') . ")");
                }
                $conn->query("UPDATE dmirror_purchases SET items_count=" . count($items) . ", attachments=" . count($att) . " WHERE id=$pid");
                $deep_done++;
            }
        }

        $conn->query("UPDATE dmirror_runs SET ended_at=NOW(), fetched=$fetched, changed=$changed, ok=1, note='" . $conn->real_escape_string("deep=$deep_done errors=" . count($errors)) . "' WHERE id=$run_id");

        echo json_encode(['success'=>true, 'run_id'=>$run_id, 'fetched'=>$fetched, 'changed'=>$changed, 'deep_synced'=>$deep_done, 'errors'=>count($errors)], JSON_UNESCAPED_UNICODE);
        break;
    }

    case 'dmirror_status': {
        $out = ['success'=>true];
        foreach (['dmirror_purchases'=>'purchases','dmirror_purchase_items'=>'items','dmirror_payments'=>'payments','dmirror_attachments'=>'attachments'] as $t=>$k) {
            $r = $conn->query("SELECT COUNT(*) c FROM $t");
            $row = $r ? $r->fetch_assoc() : ['c'=>0];
            $out['counts'][$k] = (int)$row['c'];
        }
        $r = $conn->query("SELECT COALESCE(SUM(total),0) s FROM dmirror_purchases");
        $out['total_value'] = $r ? round((float)$r->fetch_assoc()['s'], 2) : 0;
        $out['attachment_kinds'] = [];
        if ($kr = $conn->query("SELECT COALESCE(entity_key,'—') k, COUNT(*) n FROM dmirror_attachments
                                GROUP BY entity_key ORDER BY n DESC"))
            while ($kx = $kr->fetch_assoc()) $out['attachment_kinds'][$kx['k']] = (int)$kx['n'];
        // كم مرفقاً من دفترة صار عندنا نسخة منه — لمتابعة الأرشفة
        if ($ar = $conn->query("SELECT COUNT(*) n FROM dmirror_attachments at
                JOIN purchase_documents pd ON pd.daftra_file_id = at.file_id
                     AND pd.drive_url IS NOT NULL AND pd.drive_url <> ''
                WHERE at.entity_key IN ('purchase_order','purchase_invoice')"))
            $out['counts']['attachments_archived'] = (int)$ar->fetch_assoc()['n'];
        $r = $conn->query("SELECT * FROM dmirror_runs ORDER BY id DESC LIMIT 5");
        $out['runs'] = []; if ($r) while ($x = $r->fetch_assoc()) $out['runs'][] = $x;
        $r = $conn->query("SELECT * FROM dmirror_changes ORDER BY id DESC LIMIT 30");
        $out['recent_changes'] = []; if ($r) while ($x = $r->fetch_assoc()) $out['recent_changes'][] = $x;
        echo json_encode($out, JSON_UNESCAPED_UNICODE);
        break;
    }

    case 'daftra_purchases_list':
        set_time_limit(30);
        $dk   = "__DAFTRA_KEY__";
        $page = (int)($_GET['page'] ?? 1);
        $lim_pur = (int)($_GET['limit'] ?? 50);
        $from = $_GET['from'] ?? ''; $to = $_GET['to'] ?? '';
        $supplier_id_filter = (int)($_GET['supplier_id'] ?? 0);
        $qp   = "page=$page&limit=$lim_pur";
        if ($from) $qp .= "&from_date=$from";
        if ($to)   $qp .= "&to_date=$to";
        if ($supplier_id_filter) $qp .= "&supplier_id=$supplier_id_filter";
        $ch = curl_init("https://semak.daftra.com/api2/purchase_invoices.json?$qp");
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_HTTPHEADER=>["APIKEY: $dk","Accept: application/json"], CURLOPT_TIMEOUT=>15, CURLOPT_FOLLOWLOCATION=>true]);
        $res = curl_exec($ch); curl_close($ch);
        $data = json_decode($res, true) ?? [];
        $rows = [];
        foreach ($data['data'] ?? [] as $r) {
            $p = $r['PurchaseInvoice'] ?? $r['PurchaseOrder'] ?? $r;
            $rows[] = [
                'id'           => $p['id'],
                'no'           => $p['no']   ?? '',
                'date'         => $p['date'] ?? '',
                'supplier_id'  => $p['supplier_id'] ?? '',
                'supplier'     => $p['supplier_business_name'] ?? '',
                'total'        => (float)($p['summary_total'] ?? $p['grand_total'] ?? 0),
                'paid'         => (float)($p['summary_paid']  ?? 0),
                'work_order_id'=> $p['work_order_id'] ?? null,
            ];
        }

        // ─── فواتير أُدخلت من تطبيق المشتريات: تعيش عندنا لا في دفترة ─────────
        // القائمة تُبنى من دفترة، فلولا هذا الدمج لاختفت الفاتورة التي يحفظها
        // مدير المشتريات من جواله رغم أنها محفوظة فعلاً.
        $seen = [];
        foreach ($rows as $r0) $seen[(int)$r0['id']] = 1;
        $lw = ["origin = 'local'"];
        if (preg_match('/^d{4}-d{2}-d{2}$/', (string)$from)) $lw[] = "date >= '" . $conn->real_escape_string($from) . "'";
        if (preg_match('/^d{4}-d{2}-d{2}$/', (string)$to))   $lw[] = "date <= '" . $conn->real_escape_string($to) . "'";
        if ($supplier_id_filter) $lw[] = "supplier_id = $supplier_id_filter";
        $lr = $conn->query("SELECT id, no, date, supplier_id, supplier, total, paid, work_order_id
                            FROM dmirror_purchases WHERE " . implode(' AND ', $lw) . " ORDER BY date DESC, id DESC LIMIT 200");
        if ($lr) while ($lx = $lr->fetch_assoc()) {
            if (isset($seen[(int)$lx['id']])) continue;
            $rows[] = [
                'id'           => (int)$lx['id'],
                'no'           => $lx['no'] ?? '',
                'date'         => $lx['date'] ?? '',
                'supplier_id'  => $lx['supplier_id'] ?? '',
                'supplier'     => $lx['supplier'] ?? '',
                'total'        => (float)$lx['total'],
                'paid'         => (float)$lx['paid'],
                'work_order_id'=> $lx['work_order_id'],
                'origin'       => 'local',
            ];
        }
        usort($rows, function($a, $b) {
            $c = strcmp((string)($b['date'] ?? ''), (string)($a['date'] ?? ''));
            return $c !== 0 ? $c : ((int)$b['id'] <=> (int)$a['id']);
        });

        // ─── تصنيف تلقائي: الفاتورة الجديدة ترث البند الغالب لموردها ──────────
        // (البوابة تبقى محدثة: أي فاتورة تدخل دفترة تُصنَّف فور أول عرض للقائمة،
        //  والمورد الجديد كلياً يبقى «غير مصنف» بانتظار قرار يدوي)
        if ($rows) {
            $ids = implode(',', array_map('intval', array_column($rows, 'id')));
            $classified = [];
            $cr = $conn->query("SELECT ref_id, code FROM purchase_classification WHERE kind='purchase' AND ref_id IN ($ids)");
            if ($cr) while ($c = $cr->fetch_assoc()) $classified[(int)$c['ref_id']] = $c['code'];

            // تفصيل أصناف كل فاتورة (لفلترة «تحتوي الصنف»)
            $itemCodes = [];
            $ir = $conn->query("SELECT ref_id, code FROM purchase_class_items WHERE ref_id IN ($ids)");
            if ($ir) while ($ic = $ir->fetch_assoc()) $itemCodes[(int)$ic['ref_id']][] = $ic['code'];

            // البند الغالب لكل مورد (من التصنيفات القائمة)
            $supCode = [];
            $sr = $conn->query("SELECT supplier_id, code, COUNT(*) AS n FROM purchase_classification
                                WHERE kind='purchase' AND supplier_id IS NOT NULL
                                GROUP BY supplier_id, code ORDER BY supplier_id, n ASC");
            if ($sr) while ($s = $sr->fetch_assoc()) $supCode[(int)$s['supplier_id']] = $s['code']; // الأخير = الأكثر تكراراً

            foreach ($rows as $i => $row) {
                $rid = (int)$row['id'];
                $rows[$i]['class_codes'] = array_values(array_unique(array_merge(
                    $itemCodes[$rid] ?? [],
                    isset($classified[$rid]) ? [$classified[$rid]] : []
                )));
                if (isset($classified[$rid])) { $rows[$i]['class_code'] = $classified[$rid]; continue; }
                $sid = (int)$row['supplier_id'];
                if ($sid > 0 && isset($supCode[$sid])) {
                    $code = $conn->real_escape_string($supCode[$sid]);
                    if ($conn->query("INSERT INTO purchase_classification (kind, ref_id, code, supplier_id, source)
                                      VALUES ('purchase', $rid, '$code', $sid, 'supplier')
                                      ON DUPLICATE KEY UPDATE code=code")) {
                        $rows[$i]['class_code'] = $supCode[$sid];
                        $rows[$i]['class_codes'][] = $supCode[$sid];
                        continue;
                    }
                }
                $rows[$i]['class_code'] = '';
            }
        }
        echo json_encode(['success'=>true,'data'=>$rows], JSON_UNESCAPED_UNICODE);
        break;

    case 'daftra_purchase_create':
    case 'daftra_purchase_update':
        $dk   = "__DAFTRA_KEY__";
        $body = json_decode(file_get_contents('php://input'), true) ?? [];
        $pur_id    = (int)($body['id'] ?? $_GET['id'] ?? 0);
        $is_update = ($action === 'daftra_purchase_update' && $pur_id > 0);
        $url    = $is_update
            ? "https://semak.daftra.com/api2/purchase_invoices/$pur_id.json"
            : "https://semak.daftra.com/api2/purchase_invoices.json";
        $items = [];
        foreach ($body['items'] ?? [] as $it) {
            $items[] = ['name'=>$it['name']??'','quantity'=>(float)($it['quantity']??1),'unit_price'=>(float)($it['unit_price']??0),'discount'=>(float)($it['discount']??0),'tax'=>(float)($it['tax']??15)];
        }
        $payload = ['PurchaseInvoice' => [
            'supplier_id'   => $body['supplier_id']   ?? '',
            'date'          => $body['date']          ?? date('Y-m-d'),
            'work_order_id' => $body['work_order_id'] ?? null,
            'notes'         => $body['notes']         ?? '',
            'PurchaseInvoiceItem' => $items,
        ]];
        $ch = curl_init($url);
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_HTTPHEADER=>["APIKEY: $dk","Accept: application/json","Content-Type: application/json"], CURLOPT_CUSTOMREQUEST=>($is_update?'PUT':'POST'), CURLOPT_POSTFIELDS=>json_encode($payload,JSON_UNESCAPED_UNICODE), CURLOPT_TIMEOUT=>20, CURLOPT_FOLLOWLOCATION=>true]);
        $res = curl_exec($ch); $code = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        echo json_encode(['success'=>in_array($code,[200,201]),'http_code'=>$code,'data'=>json_decode($res,true),'message'=>in_array($code,[200,201])?'تمّ بنجاح':'فشل'], JSON_UNESCAPED_UNICODE);
        break;

    case 'daftra_purchase_set_project': {
        // تسكين فواتير على مشروع — يرسل work_order_id فقط (لا يمس البنود/المورد/التاريخ)
        set_time_limit(120);
        $dk = "__DAFTRA_KEY__";
        $b = json_decode(file_get_contents('php://input'), true) ?: [];
        $clearMode = !empty($b['clear']); // إزالة تسكين الفاتورة من أي مشروع (شخصي/غير متعلق بالشركة)
        $wid = (int)($b['work_order_id'] ?? 0);
        $ids = array_slice(array_values(array_filter(array_map('intval', (array)($b['ids'] ?? [])))), 0, 60);
        if (!$ids || (!$wid && !$clearMode)) { echo json_encode(['success'=>false,'message'=>'ids وwork_order_id مطلوبان']); break; }
        $out = [];
        // مسار بديل: تحديث جزئي عبر v2 entity API (حقل واحد فقط) — لا يعيد بناء الفاتورة فلا يُفعّل تحقق إرسال البريد
        if (!empty($b['via_v2'])) {
            foreach ($ids as $pid2) {
                $chP = curl_init("https://semak.daftra.com/v2/api/entity/purchase_invoice/$pid2");
                curl_setopt_array($chP, [
                    CURLOPT_RETURNTRANSFER => true,
                    CURLOPT_CUSTOMREQUEST  => 'PUT',
                    CURLOPT_POSTFIELDS     => json_encode(['work_order_id' => $wid], JSON_UNESCAPED_UNICODE),
                    CURLOPT_HTTPHEADER     => ["APIKEY: $dk", "Accept: application/json", "Content-Type: application/json"],
                    CURLOPT_TIMEOUT => 15, CURLOPT_FOLLOWLOCATION => true,
                ]);
                $resP = curl_exec($chP); $code = curl_getinfo($chP, CURLINFO_HTTP_CODE); curl_close($chP);
                $out[$pid2] = ($code >= 200 && $code < 300) ? $code : ['code'=>$code, 'err'=>mb_substr((string)$resP, 0, 400)];
            }
            echo json_encode(['success'=>true, 'results'=>$out, 'via'=>'v2_patch'], JSON_UNESCAPED_UNICODE);
            break;
        }
        foreach ($ids as $pid2) {
            // 1) اجلب حقول الفاتورة الأساسية كما هي (دفترة ترفض PUT جزئياً — 400)
            $chG = curl_init("https://semak.daftra.com/api2/purchase_invoices/$pid2.json");
            curl_setopt_array($chG, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_HTTPHEADER=>["APIKEY: $dk","Accept: application/json"], CURLOPT_TIMEOUT=>12, CURLOPT_FOLLOWLOCATION=>true]);
            $resG = curl_exec($chG); curl_close($chG);
            $dG = json_decode($resG, true) ?: [];
            $invG = $dG['data']['PurchaseOrder'] ?? $dG['data']['PurchaseInvoice'] ?? [];
            if (!$invG) { $out[$pid2] = 'fetch_failed'; continue; }
            // تطبيع التاريخ (يرد أحياناً dd/mm/yyyy)
            $rd = (string)($invG['date'] ?? '');
            if (preg_match('#^(\d{2})/(\d{2})/(\d{4})#', $rd, $dm2))      $rd = "{$dm2[3]}-{$dm2[2]}-{$dm2[1]}";
            elseif (!preg_match('/^\d{4}-\d{2}-\d{2}/', $rd))            $rd = date('Y-m-d');
            else                                                          $rd = substr($rd, 0, 10);
            // 2) أعد الفاتورة كاملة كما جُلبت (بنودها حرفياً) + المشروع الجديد — دفترة ترفض الجزئي
            $itemsP = [];
            foreach ((array)($invG['PurchaseOrderItem'] ?? $invG['PurchaseInvoiceItem'] ?? []) as $itG) {
                if (!is_array($itG)) continue;
                $row = [
                    'item'       => $itG['item'] ?? $itG['name'] ?? '',
                    'name'       => $itG['item'] ?? $itG['name'] ?? '',
                    'quantity'   => (float)($itG['quantity'] ?? 1),
                    'unit_price' => (float)($itG['unit_price'] ?? 0),
                    'discount'   => (float)($itG['discount'] ?? 0),
                    'tax1'       => $itG['tax1'] ?? '',
                ];
                if (!empty($itG['id']))         $row['id'] = (int)$itG['id'];
                if (!empty($itG['product_id'])) $row['product_id'] = (int)$itG['product_id'];
                if (isset($itG['description']) && $itG['description'] !== '') $row['description'] = $itG['description'];
                $itemsP[] = $row;
            }
            // مرونة تجريب: wrapper وحقول إضافية من الطلب (لاكتشاف صيغة دفترة المقبولة)
            $wrapper = preg_match('/^[A-Za-z]{3,40}$/', (string)($b['wrapper'] ?? '')) ? $b['wrapper'] : 'PurchaseInvoice';
            $inner = [
                'supplier_id'    => (int)($invG['supplier_id'] ?? 0),
                'date'           => $rd,
                'notes'          => $invG['notes'] ?? '',
                'work_order_id'  => $wid,
                // تمرير حقول الإرسال والأعلام كما هي — دفترة تتحقق من supplier_email عند علم الإرسال
                // إن كان بريد المورد فارغاً (أغلب الموردين المحليين) نستخدم بريد احمد الداخلي فقط لتجاوز التحقق — لا يُغيّر بريد المورد الفعلي في دفترة
                'supplier_email' => $invG['supplier_email'] ?: 'ahmed.albadi@semak.sa',
                'is_offline'     => $invG['is_offline'] ?? 1,
                'draft'          => $invG['draft'] ?? 0,
            ];
            // حافظ على رقم الفاتورة الأصلي — بدون هذا الحقل دفترة تولّد رقماً جديداً عند كل PUT
            if (!empty($invG['no'])) $inner['no'] = $invG['no'];
            $itemsKey = preg_match('/^[A-Za-z]{3,40}$/', (string)($b['items_key'] ?? '')) ? $b['items_key'] : ($wrapper . 'Item');
            foreach ((array)($b['extra'] ?? []) as $ek => $ev) {
                if (preg_match('/^[a-z_0-9]{1,40}$/', (string)$ek)) $inner[$ek] = $ev;
            }
            $payloadP = [$wrapper => $inner];
            if (empty($b['no_items'])) {
                if (!empty($b['items_outside'])) $payloadP[$itemsKey] = $itemsP;   // نمط Cake: البنود أخ للغلاف
                else                             $payloadP[$wrapper][$itemsKey] = $itemsP;
            }
            $chP = curl_init("https://semak.daftra.com/api2/purchase_invoices/$pid2.json");
            curl_setopt_array($chP, [
                CURLOPT_RETURNTRANSFER => true,
                CURLOPT_CUSTOMREQUEST  => 'PUT',
                CURLOPT_POSTFIELDS     => json_encode($payloadP, JSON_UNESCAPED_UNICODE),
                CURLOPT_HTTPHEADER     => ["APIKEY: $dk", "Accept: application/json", "Content-Type: application/json"],
                CURLOPT_TIMEOUT => 15, CURLOPT_FOLLOWLOCATION => true,
            ]);
            $resP = curl_exec($chP); $code = curl_getinfo($chP, CURLINFO_HTTP_CODE); curl_close($chP);
            $out[$pid2] = ($code >= 200 && $code < 300) ? $code : ['code'=>$code, 'err'=>mb_substr((string)$resP, 0, 400)];
        }
        echo json_encode(['success'=>true, 'results'=>$out], JSON_UNESCAPED_UNICODE);
        break;
    }

    case 'daftra_purchase_items': {
        // بنود فاتورة شراء (المواد والكميات) — للمواصفات المرجعية
        if (!$_jwt_claims) { echo json_encode(['success'=>false,'message'=>'يتطلب تسجيل الدخول'], JSON_UNESCAPED_UNICODE); break; }
        $dk = "__DAFTRA_KEY__"; $pid = (int)($_GET['id'] ?? 0);
        if (!$pid) { echo json_encode(['success'=>false]); break; }
        // v2 entity API يرجع البنود كاملة
        $ch = curl_init("https://semak.daftra.com/v2/api/entity/purchase_invoice/$pid");
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_HTTPHEADER=>["APIKEY: $dk","Accept: application/json"], CURLOPT_TIMEOUT=>15, CURLOPT_FOLLOWLOCATION=>true]);
        $res = curl_exec($ch); $code = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        if ($code !== 200) {
            // احتياط: api2 مع include للبنود
            $ch = curl_init("https://semak.daftra.com/api2/purchase_invoices/$pid.json?include=items");
            curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_HTTPHEADER=>["APIKEY: $dk","Accept: application/json"], CURLOPT_TIMEOUT=>15, CURLOPT_FOLLOWLOCATION=>true]);
            $res = curl_exec($ch); $code = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        }
        header('Content-Type: application/json; charset=utf-8');
        echo $code === 200 && $res ? $res : json_encode(['success'=>false,'http'=>$code]);
        break;
    }

    case 'daftra_purchase_get':
        // جلب تفاصيل مشتراة واحدة (بما في ذلك المرفقات والبنود)
        $dk = "__DAFTRA_KEY__"; $pur_id = (int)($_GET['id'] ?? 0);
        if (!$pur_id) { echo json_encode(['success'=>false,'message'=>'id مطلوب']); break; }
        $ch = curl_init("https://semak.daftra.com/api2/purchase_invoices/$pur_id.json");
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_HTTPHEADER=>["APIKEY: $dk","Accept: application/json"], CURLOPT_TIMEOUT=>15, CURLOPT_FOLLOWLOCATION=>true]);
        $res = curl_exec($ch); $code = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        $data = json_decode($res, true) ?? [];
        echo json_encode(['success'=>$code===200,'http_code'=>$code,'data'=>$data], JSON_UNESCAPED_UNICODE);
        break;

    case 'daftra_attachment_download':
        // تحميل مرفق من دفترة عبر المسار (path) باستخدام /s3/ + session cookie
        $path = $_GET['path'] ?? '';
        if (!$path) { echo json_encode(['success'=>false,'message'=>'path مطلوب (مثال: files/11ddb74/purchase_order/UUID.pdf)']); break; }
        $session = daftra_session_cookie($conn);
        $url = "https://semak.daftra.com/s3/" . ltrim($path, '/');
        $ch = curl_init($url);
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_FOLLOWLOCATION => true,
            CURLOPT_MAXREDIRS => 5,
            CURLOPT_TIMEOUT => 30,
            CURLOPT_COOKIE => "daftra_session=$session",
            CURLOPT_HTTPHEADER => ["Accept: */*"],
        ]);
        $res = curl_exec($ch);
        $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        $ct = curl_getinfo($ch, CURLINFO_CONTENT_TYPE);
        $finalUrl = curl_getinfo($ch, CURLINFO_EFFECTIVE_URL);
        curl_close($ch);
        if ($code === 200 && strlen($res) > 100) {
            echo json_encode([
                'success' => true,
                'http_code' => $code,
                'content_type' => $ct,
                'size' => strlen($res),
                'base64' => base64_encode($res),
            ], JSON_UNESCAPED_UNICODE);
        } else {
            echo json_encode([
                'success' => false,
                'http_code' => $code,
                'content_type' => $ct,
                'size' => strlen($res),
                'final_url_domain' => parse_url($finalUrl, PHP_URL_HOST),
            ], JSON_UNESCAPED_UNICODE);
        }
        break;

    case 'daftra_purchase_delete':
        $dk = "__DAFTRA_KEY__"; $pur_id = (int)($_GET['id'] ?? 0);
        $ch = curl_init("https://semak.daftra.com/api2/purchase_invoices/$pur_id.json");
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_HTTPHEADER=>["APIKEY: $dk"], CURLOPT_CUSTOMREQUEST=>'DELETE', CURLOPT_TIMEOUT=>15]);
        curl_exec($ch); $code = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        echo json_encode(['success'=>in_array($code,[200,202,204]),'http_code'=>$code]);
        break;

    // ══════════════════════════════════════════════════════════════════════
    // وحدة الخزاين
    // ══════════════════════════════════════════════════════════════════════

    case 'daftra_treasuries':
        $dk = "__DAFTRA_KEY__";
        $ch = curl_init("https://semak.daftra.com/api2/treasuries.json");
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_HTTPHEADER=>["APIKEY: $dk","Accept: application/json"], CURLOPT_TIMEOUT=>15, CURLOPT_FOLLOWLOCATION=>true]);
        $res = curl_exec($ch); $code = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        $data = json_decode($res, true) ?? [];
        $rows = [];
        foreach ($data['data'] ?? [] as $r) {
            $t = $r['Treasury'] ?? $r;
            $rows[] = ['id'=>$t['id'],'name'=>$t['name']??'','balance'=>(float)($t['balance']??0),'currency'=>$t['currency_code']??'SAR','status'=>$t['status']??1];
        }
        echo json_encode(['success'=>true,'data'=>$rows,'http_code'=>$code,'raw_count'=>count($data['data']??[])], JSON_UNESCAPED_UNICODE);
        break;

    case 'daftra_treasury_transactions':
        $dk  = "__DAFTRA_KEY__";
        $tid = (int)($_GET['treasury_id'] ?? 0);
        $from= $_GET['from'] ?? ''; $to = $_GET['to'] ?? '';
        $qp  = $tid ? "treasury_id=$tid" : '';
        if ($from) $qp .= ($qp?'&':'')."from_date=$from";
        if ($to)   $qp .= ($qp?'&':'')."to_date=$to";
        $ch = curl_init("https://semak.daftra.com/api2/treasury_transactions.json".($qp?"?$qp":''));
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_HTTPHEADER=>["APIKEY: $dk","Accept: application/json"], CURLOPT_TIMEOUT=>15, CURLOPT_FOLLOWLOCATION=>true]);
        $res = curl_exec($ch); curl_close($ch);
        $data = json_decode($res, true) ?? [];
        $rows = [];
        foreach ($data['data'] ?? [] as $r) {
            $tx = $r['TreasuryTransaction'] ?? $r;
            $rows[] = ['id'=>$tx['id'],'date'=>$tx['date']??'','type'=>$tx['type']??'','amount'=>(float)($tx['amount']??0),'notes'=>$tx['notes']??'','treasury_id'=>$tx['treasury_id']??'','treasury'=>$tx['treasury_name']??''];
        }
        echo json_encode(['success'=>true,'data'=>$rows], JSON_UNESCAPED_UNICODE);
        break;

    case 'daftra_treasury_add':
        $dk   = "__DAFTRA_KEY__";
        $body = json_decode(file_get_contents('php://input'), true) ?? [];
        $payload = ['TreasuryTransaction' => [
            'treasury_id' => $body['treasury_id'] ?? '',
            'type'        => $body['type']        ?? 'in',
            'date'        => $body['date']        ?? date('Y-m-d'),
            'amount'      => (float)($body['amount'] ?? 0),
            'notes'       => $body['notes']       ?? '',
        ]];
        $ch = curl_init("https://semak.daftra.com/api2/treasury_transactions.json");
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_HTTPHEADER=>["APIKEY: $dk","Accept: application/json","Content-Type: application/json"], CURLOPT_POST=>true, CURLOPT_POSTFIELDS=>json_encode($payload,JSON_UNESCAPED_UNICODE), CURLOPT_TIMEOUT=>20]);
        $res = curl_exec($ch); $code = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        echo json_encode(['success'=>in_array($code,[200,201]),'http_code'=>$code,'data'=>json_decode($res,true)], JSON_UNESCAPED_UNICODE);
        break;

    // ══════════════════════════════════════════════════════════════════════
