            $pmap=[]; $pr=$conn->query("SELECT id,name FROM acc_parties WHERE tenant_id=$tid AND type='partner'"); while($pr&&($x=$pr->fetch_assoc())) $pmap[trim($x['name'])]=(int)$x['id'];
