                if(strpos($c,'1203')===0 || strpos($c,'1204')===0) $arLeaves[]=['code'=>$c,'name'=>$nm,'net'=>$net,'entity_id'=>$entId,'entity_type'=>$entTy];
                elseif(strpos($c,'221')===0)                       $apLeaves[]=['code'=>$c,'name'=>$nm,'net'=>$net,'entity_id'=>$entId,'entity_type'=>$entTy];
