            while($r&&($x=$r->fetch_assoc())){ if($x['daftra_id']!==null&&$x['daftra_id']!=='') $byD[(string)$x['daftra_id']]=(int)$x['id']; $byN[mb_strtolower(trim($x['name']))]=(int)$x['id']; }
            return ['d'=>$byD,'n'=>$byN];
